"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[70384],{3084:(e,i,a)=>{a.r(i),a.d(i,{assets:()=>s,contentTitle:()=>l,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>c});const o=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arresto per l\'omicidio di Bob Lee a SF: anche il presunto assassino lavorava nel settore tecnologico","source":"@site/i18n/it/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/it/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/it/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14 aprile 2023","top_news":"Arresto per l\'omicidio di Bob Lee a SF: anche il presunto assassino lavorava nel settore tecnologico"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/it/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/it/2023/04/13"}}');var t=a(23420),n=a(3331);const r={localized_date:"14 aprile 2023",top_news:"Arresto per l'omicidio di Bob Lee a SF: anche il presunto assassino lavorava nel settore tecnologico"},l="2023-04-14",s={},c=[{value:"Arresto per l&#39;omicidio di Bob Lee a SF: anche il presunto assassino lavorava nel settore tecnologico",id:"arresto-per-lomicidio-di-bob-lee-a-sf-anche-il-presunto-assassino-lavorava-nel-settore-tecnologico",level:2},{value:"Il divieto di ospitare YouTube-DL apre la strada alla censura privatizzata",id:"il-divieto-di-ospitare-youtube-dl-apre-la-strada-alla-censura-privatizzata",level:2},{value:"L&#39;arte dell&#39;auto-ingegneria",id:"larte-dellauto-ingegneria",level:2},{value:"Apple utilizzer\xe0 il 100% di cobalto riciclato nelle batterie entro il 2025",id:"apple-utilizzer\xe0-il-100-di-cobalto-riciclato-nelle-batterie-entro-il-2025",level:2},{value:"Abbiamo ottenuto un incremento di 6 volte della velocit\xe0 di avvio di Podman",id:"abbiamo-ottenuto-un-incremento-di-6-volte-della-velocit\xe0-di-avvio-di-podman",level:2},{value:"Migliorare Tailscale attraverso l&#39;open source di Apple",id:"migliorare-tailscale-attraverso-lopen-source-di-apple",level:2},{value:"Disegni animati",id:"disegni-animati",level:2},{value:"Amazon CodeWhisperer, gratuito per uso individuale, \xe8 ora generalmente disponibile",id:"amazon-codewhisperer-gratuito-per-uso-individuale-\xe8-ora-generalmente-disponibile",level:2},{value:"Google ha gi\xe0 ritirato sei prodotti nel 2023.",id:"google-ha-gi\xe0-ritirato-sei-prodotti-nel-2023",level:2},{value:"Nvidia RTX Remix Runtime Open Source disponibile ora",id:"nvidia-rtx-remix-runtime-open-source-disponibile-ora",level:2}];function d(e){const i={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,n.R)(),...e.components};return(0,t.jsxs)(t.Fragment,{children:[(0,t.jsx)(i.header,{children:(0,t.jsx)(i.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,t.jsx)(i.h2,{id:"arresto-per-lomicidio-di-bob-lee-a-sf-anche-il-presunto-assassino-lavorava-nel-settore-tecnologico",children:"Arresto per l'omicidio di Bob Lee a SF: anche il presunto assassino lavorava nel settore tecnologico"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"Originale"}),".\n\xc8 stato effettuato un arresto per l'omicidio del dirigente tecnologico Bob Lee; anche il presunto assassino lavorava nel settore tecnologico ed era conosciuto da Lee. Secondo quanto riferito dalla polizia, Lee e il sospettato stavano guidando insieme in un'auto intestata a quest'ultimo e sostengono che ci sia stato un qualche tipo di scontro mentre si trovava a bordo del veicolo, che potrebbe essere continuato anche dopo che Lee se n'era andato. La notizia della morte di Lee \xe8 stata accostata ad altre disgrazie e crimini recenti di San Francisco, anche se ci\xf2 non rappresenta con precisione l'esperienza reale della maggior parte dei cittadini di San Francisco."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nL'omicidio di un dirigente tecnologico a San Francisco ha suscitato discussioni su fattori come la mancanza di casa, la salute mentale, la tossicodipendenza e la povert\xe0 che possono aver portato al crimine, ma i commentatori mettono in guardia dal fare generalizzazioni. Si discute anche sull'uso delle statistiche rispetto agli aneddoti personali nel valutare i tassi di criminalit\xe0 e sulla necessit\xe0 di un approccio che coinvolga la comunit\xe0 per affrontare le complesse questioni dei senzatetto, delle dipendenze e della criminalit\xe0. Gli utenti sottolineano l'importanza di valutare i livelli di criminalit\xe0 in relazione alla povert\xe0, piuttosto che paragonare culture diverse e non saltare a conclusioni basate su un solo caso."]}),"\n",(0,t.jsx)(i.h2,{id:"il-divieto-di-ospitare-youtube-dl-apre-la-strada-alla-censura-privatizzata",children:"Il divieto di ospitare YouTube-DL apre la strada alla censura privatizzata"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"Originale"}),'.\nUn tribunale tedesco ha dichiarato Uberspace responsabile di aver ospitato il sito web di youtube-dl, uno strumento open-source che consente di scaricare i contenuti di YouTube. Uberspace avverte che il verdetto potrebbe portare a una censura privatizzata e sta facendo appello alla decisione, anche se il tribunale ha ritenuto che Uberspace "pu\xf2 essere ritenuto responsabile per aver dubitato della validit\xe0 di una richiesta di takedown", anche quando non era chiaro che lo strumento violasse la legge.']}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nIl divieto di hosting su YouTube-DL \xe8 visto come una spinta verso la censura privatizzata, con la RIAA e la MPAA che privilegiano il denaro e il potere rispetto alla decenza. Il ruolo della propriet\xe0 intellettuale nel limitare il flusso di informazioni \xe8 oggetto di dibattito, con una serie di punti di vista che includono la limitazione della portata e della durata. Gli utenti propongono alternative e denunciano la dipendenza da GitHub, discutendo al contempo la decentralizzazione e i problemi della sicurezza per oscurit\xe0 nella protezione delle copie."]}),"\n",(0,t.jsx)(i.h2,{id:"larte-dellauto-ingegneria",children:"L'arte dell'auto-ingegneria"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.howacarworks.com/video-course",children:"Originale"}),".\nThe Art of Auto Engineering \xe8 un videocorso completo composto da oltre 122 lezioni con 20 ore di filmati che spiegano ogni singola parte di un'auto in modo dettagliato, coprendo le basi fino all'ingegneria automobilistica avanzata. Il corso \xe8 accompagnato da un manuale di 200 pagine ed \xe8 disponibile online o su app per iOS e Android con un pagamento unico di 25 dollari e accesso a vita, ed \xe8 filmato professionalmente in qualit\xe0 4K con sottotitoli completi. Il corso \xe8 apprezzato dagli spettatori per le sue lezioni coinvolgenti e l'eccellente valore di produzione."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nGli utenti di Hacker News condividono esperienze e consigliano risorse per imparare l'ingegneria automobilistica, tra cui corsi video interattivi e modelli di auto specifici. I commentatori discutono i vantaggi della comprensione della meccanica automobilistica, i limiti dell'affidarsi esclusivamente all'intelligenza artificiale e forniscono suggerimenti per le riparazioni auto fai da te. Inoltre, gli utenti discutono dell'utilit\xe0 dei corsi e degli strumenti a pagamento e alcuni criticano l'apparizione di pubblicit\xe0 di corsi a pagamento sul sito."]}),"\n",(0,t.jsx)(i.h2,{id:"apple-utilizzer\xe0-il-100-di-cobalto-riciclato-nelle-batterie-entro-il-2025",children:"Apple utilizzer\xe0 il 100% di cobalto riciclato nelle batterie entro il 2025"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"Originale"}),".\nApple ha annunciato il suo piano per utilizzare il 100% di cobalto riciclato in tutte le batterie progettate da Apple entro il 2025, insieme a elementi di terre rare interamente riciclati per i magneti e al 100% di stagno riciclato per i circuiti stampati. L'obiettivo \xe8 quello di utilizzare solo materiali riciclati e rinnovabili e gi\xe0 oggi si rifornisce di oltre il 95% del tungsteno, di quasi tre quarti delle terre rare e di oltre due terzi dell'alluminio da materiale riciclato al 100%. Apple utilizza la realt\xe0 aumentata (AR) per guidare lo smontaggio dei dispositivi per i partner che si occupano di riciclaggio e aumentare il recupero degli elementi di terre rare, guidando cos\xec il cambiamento dell'industria verso la riduzione della dipendenza da minerali di nuova estrazione."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple ha annunciato l'intenzione di utilizzare il 100% di cobalto riciclato nelle batterie entro il 2025 e di ridurre i rifiuti di plastica, ma gli utenti discutono sull'efficacia di questi cambiamenti e sull'opportunit\xe0 che l'azienda renda pubbliche le sue tecnologie di riciclaggio. Il dibattito sulle batterie sostituibili dall'utente continua, con argomentazioni che le ritengono negative per l'ambiente, mentre altri suggeriscono che i metodi di riciclaggio e l'estensione della durata dei prodotti possono risolvere il problema. L'impegno di Apple nei confronti dei materiali riciclabili e di una catena di approvvigionamento neutrale dal punto di vista delle emissioni di anidride carbonica viene elogiato, ma criticato per il design e la catena di approvvigionamento del cobalto. Gli utenti discutono della durata di vita degli iPhone e dei telefoni Android e dei metodi di riciclaggio delle batterie. Alcuni utenti suggeriscono le batterie MagSafe come batteria principale per gli iPhone, mentre altri ne contestano l'efficienza."]}),"\n",(0,t.jsx)(i.h2,{id:"abbiamo-ottenuto-un-incremento-di-6-volte-della-velocit\xe0-di-avvio-di-podman",children:"Abbiamo ottenuto un incremento di 6 volte della velocit\xe0 di avvio di Podman"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Originale"}),".\nIl motore di container di Red Hat, Podman, ha ottenuto un aumento di 6 volte della velocit\xe0 di avvio eliminando i processi non necessari e risolvendo le inefficienze minori che hanno un impatto su applicazioni critiche come le automobili, dove l'avvio dei container in tempo quasi reale \xe8 essenziale. Il team ha utilizzato lo storage transitorio e ha fornito soluzioni per i problemi del kernel, ottenendo un avvio pi\xf9 rapido dei container. L'uso dell'opzione --transient-store \xe8 ideale per i dispositivi edge, anche se i container in modalit\xe0 mista non sono supportati."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nPodman di Red Hat vede un aumento di sei volte della velocit\xe0 di avvio delle auto, anche se gli utenti di Discussion Service discutono dell'eccessiva complicazione delle auto moderne e sollevano preoccupazioni sull'affidabilit\xe0 e la manutenzione. La discussione si sposta sul diritto alla riparazione, sull'uso di microservizi e container e sull'equilibrio tra progressi tecnologici e praticit\xe0."]}),"\n",(0,t.jsx)(i.h2,{id:"migliorare-tailscale-attraverso-lopen-source-di-apple",children:"Migliorare Tailscale attraverso l'open source di Apple"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Originale"}),".\nIl team di Tailscale ha usato l'open source di Apple per debuggare i bug relativi all'interfaccia di rete per la versione 1.36, basandosi su ifconfig per determinare l'interfaccia di rete attiva. Quando Tailscale \xe8 configurato per utilizzare un nodo di uscita, questo diventa il percorso predefinito, rendendo necessaria una correzione per \"legare\" in modo coerente le richieste di rete all'interfaccia di rete attiva senza causare il looping del traffico. SIOCGIFDELEGATE, disponibile tramite ioctl, consente di ottenere l'interfaccia fisica sottostante ed \xe8 stato implementato nel codice di Tailscale per macOS e iOS."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nGli utenti di Discussion Service discutono i vantaggi e le sfide del software open e closed source nel miglioramento di Tailscale attraverso l'open source di Apple. Alcuni clienti paganti danno priorit\xe0 alla reputazione del prodotto principale open source di Tailscale, mentre altri sollevano problemi specifici con Tailscale, come la difficolt\xe0 di accesso alle condivisioni di rete su Windows 11 e il potenziale consumo di batteria sui dispositivi iOS. La discussione mette in evidenza l'importanza di considerare diverse prospettive e il fatto che Tailscale sta guadagnando terreno rispetto a Zerotier grazie al suo sistema mesh e alla distribuzione continua di nuove funzionalit\xe0, ma per alcuni utenti del prodotto esistono problemi di fatturato e di fossato."]}),"\n",(0,t.jsx)(i.h2,{id:"disegni-animati",children:"Disegni animati"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://fairanimateddrawings.com/site/home",children:"Originale"}),".\nIl repository \"Animated Drawings\" su Github implementa l'algoritmo descritto nell'articolo \"A Method for Automatically Animating Children's Drawings of the Human Figure\", permettendo agli utenti di creare animazioni personalizzate con i propri personaggi disegnati a mano. Il processo di installazione \xe8 semplice e i file di configurazione possono essere modificati per cambiare varie opzioni, tra cui i formati di output e le immagini di sfondo. Il repository fornisce anche script e modelli per l'animazione di disegni personali ed \xe8 disponibile una demo basata su browser per un utilizzo semplice e veloce."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nIl progetto Fair Animated Drawings anima i disegni con il codice, disponibile in una versione basata su browser e su GitHub. Gli utenti sono interessati al suo potenziale per le idee commerciali e sperano in una versione di app per Android. Un lavoro rilevante sulla stima non fotorealistica delle pose, chiamato Gesture3D, sembra applicabile a un caso d'uso specifico, e sono aperte le candidature per la YC Summer 2023."]}),"\n",(0,t.jsx)(i.h2,{id:"amazon-codewhisperer-gratuito-per-uso-individuale-\xe8-ora-generalmente-disponibile",children:"Amazon CodeWhisperer, gratuito per uso individuale, \xe8 ora generalmente disponibile"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Originale"}),".\nAmazon CodeWhisperer, un compagno di codifica AI in tempo reale, \xe8 ora generalmente disponibile e include un livello CodeWhisperer Individual, gratuito per tutti gli sviluppatori. Lo strumento aiuta gli sviluppatori a scrivere codice in modo rapido e sicuro, senza lasciare il proprio IDE. CodeWhisperer offre suggerimenti per casi d'uso generici in una variet\xe0 di linguaggi e pu\xf2 filtrare o segnalare i suggerimenti di codice che possono assomigliare a particolari dati di formazione open-source, contribuendo a ridurre il rischio di utilizzare codice potenzialmente distorto o difettoso."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer \xe8 ora generalmente disponibile e supporta diversi linguaggi, tra cui Python, Java, JavaScript, TypeScript e C#. Sebbene Copilot sia, a quanto pare, migliore di CodeWhisperer, quest'ultimo \xe8 uno strumento utile che potrebbe portare il codice generato dall'intelligenza artificiale a diventare la norma. Inoltre, Amazon ha lanciato CodeGuru Reviewer, uno strumento di intelligenza artificiale che analizza il codice per identificare i problemi e consigliare le correzioni per ridurre l'efficienza e i costi."]}),"\n",(0,t.jsx)(i.h2,{id:"google-ha-gi\xe0-ritirato-sei-prodotti-nel-2023",children:"Google ha gi\xe0 ritirato sei prodotti nel 2023."}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"Originale"}),".\nGoogle ha chiuso sei prodotti nei primi quattro mesi del 2023, tra cui il concorso di programmazione Code Jam, la piattaforma di social media Google Currents, l'app Street View, la tecnologia indossabile Google Jacquard, il servizio di cloud gaming Google Stadia e il router wireless Google OnHub. Sebbene alcuni di questi prodotti avessero pi\xf9 di dieci anni, Google ha dovuto affrontare critiche per la sua abitudine di terminare bruscamente servizi popolari."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle ha interrotto sei prodotti nel 2023, con preoccupazioni relative alla trasparenza e all'etichettatura dei prodotti e alla mancanza di supporto per iniziative fallite come Google Glass e Google Plus. Mentre l'unit\xe0 cloud sta crescendo con una quota di mercato del 10%, vengono sollevate preoccupazioni sul coinvolgimento dei clienti e degli sviluppatori e sull'algoritmo che uccide gli account. Gli utenti discutono le soluzioni e i costi per migliorare l'accuratezza di ChatGPT, mentre la reputazione di Google di abbandonare i progetti attira le critiche sul supporto ai prodotti per i consumatori."]}),"\n",(0,t.jsx)(i.h2,{id:"nvidia-rtx-remix-runtime-open-source-disponibile-ora",children:"Nvidia RTX Remix Runtime Open Source disponibile ora"}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Originale"}),".\nNvidia ha rilasciato il runtime RTX Remix, una piattaforma di modding open source per la rimasterizzazione di giochi classici DirectX 8 e 9 con path tracing, texture potenziate dall'intelligenza artificiale e risorse create dall'utente. Il toolkit per la creazione di RTX Remix consente ai modder di assegnare nuove risorse e luci all'interno di una scena rimasterizzata e di utilizzare strumenti di intelligenza artificiale per ricostruire l'aspetto di qualsiasi risorsa. Il runtime RTX Remix, invece, acquisisce una scena di gioco, sostituisce le risorse durante la riproduzione e inietta nel gioco la tecnologia RTX, come il path tracing, DLSS 3 e Reflex."]}),"\n",(0,t.jsxs)(i.p,{children:[(0,t.jsx)(i.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia ha rilasciato il suo RTX Remix Runtime open-source che consente agli utenti di giocare ai vecchi giochi con il ray tracing in tempo reale, anche se non tutti i giochi funzioneranno. Gli utenti di Hacker News discutono dell'importanza dei driver open-source rispetto a quelli proprietari, della reputazione di Nvidia e delle scarse prestazioni di RTX su hardware non Nvidia. Gli utenti ipotizzano anche potenziali favoritismi e suggeriscono di sostenere gli sviluppatori di criptovalute che implementano schemi proof-of-work solo su GPU. Un utente fa notare lo sviluppo da parte di Remedy di remake per PC di Max Payne utilizzando Remix e discute i problemi di frame pacing e stuttering della tecnologia."]})]})}function u(e={}){const{wrapper:i}={...(0,n.R)(),...e.components};return i?(0,t.jsx)(i,{...e,children:(0,t.jsx)(d,{...e})}):d(e)}},3331:(e,i,a)=>{a.d(i,{R:()=>r,x:()=>l});var o=a(36672);const t={},n=o.createContext(t);function r(e){const i=o.useContext(n);return o.useMemo((function(){return"function"==typeof e?e(i):{...i,...e}}),[i,e])}function l(e){let i;return i=e.disableParentContext?"function"==typeof e.components?e.components(t):e.components||t:r(e.components),o.createElement(n.Provider,{value:i},e.children)}}}]);